import numpy as np, itertools
lines=open('opt.xyz').read().splitlines()
n=int(lines[0]); ats=[]; xyz=[]
for l in lines[2:2+n]:
    p=l.split(); ats.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
cov={'Rh':1.45,'C':0.76,'O':0.66,'H':0.31}
bonds=[]
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d < cov[ats[i]]+cov[ats[j]]+0.45:
        bonds.append((i,j,round(d,2)))
from collections import defaultdict
nb=defaultdict(list)
for i,j,d in bonds:
    nb[i].append(j); nb[j].append(i)
for i in range(n):
    print(i,ats[i],nb[i])
